import { verify as cryptoVerify, createPublicKey } from 'node:crypto';
import { readBodyCapped } from '../core/http-body.js';
import { existsSync, readFileSync } from 'node:fs';
import { mkdir, readFile, writeFile, unlink } from 'node:fs/promises';
import { join } from 'node:path';
import { homedir } from 'node:os';
import { IOC_FEED_PUBLIC_KEY, DEFAULT_FEED_URL, DEFAULT_STALENESS_DAYS } from './public-key.js';
import type { BinaryPattern, IOCDatabase } from './database.js';
import type {
  IOCFeed,
  IOCFeedData,
  IOCFeedMetadata,
  SerializedBinaryPattern,
  SerializedRegExp,
  UpdateResult,
} from './feed-types.js';

const IOC_DIR = join(homedir(), '.vaso', 'ioc');
const FEED_FILE = 'feed.json';
const SIG_FILE = 'feed.json.sig';
const METADATA_FILE = 'metadata.json';
const FETCH_TIMEOUT_MS = 15_000;
/** Published feeds are well under 1 MiB; anything far larger is not a feed. */
const MAX_FEED_BYTES = 16 * 1024 * 1024;
/** A base64 Ed25519 signature is 88 bytes. */
const MAX_SIGNATURE_BYTES = 4096;

// ── Signature verification ──────────────────────────────────────────

export function verifyFeedSignature(
  feedBytes: Buffer,
  sigBase64: string,
  publicKeyPem: string = IOC_FEED_PUBLIC_KEY,
): boolean {
  try {
    const sig = Buffer.from(sigBase64, 'base64');
    if (sig.length !== 64) return false;
    const keyObject = createPublicKey(publicKeyPem);
    return cryptoVerify(null, feedBytes, keyObject, sig);
  } catch {
    return false;
  }
}

// ── Feed shape ──────────────────────────────────────────────────────

const IOC_FEED_KEYS = [
  'c2Ips', 'maliciousDomains', 'fileHashes', 'maliciousPublishers',
  'maliciousSkillPatterns', 'trustedSkillNames', 'trustedMCPPackages', 'binaryPatterns',
] as const;

/**
 * Whether signed feed data is an IOC feed. The advisory feed is signed with
 * the same key, so a signature alone doesn't say which feed a URL served:
 * `vaso update --url <advisory feed>` must not land in the IOC cache.
 */
export function isIOCFeedData(data: unknown): data is IOCFeedData {
  if (!data || typeof data !== 'object' || Array.isArray(data)) return false;
  const record = data as Record<string, unknown>;
  if ('advisories' in record) return false;
  return IOC_FEED_KEYS.every((k) => record[k] === undefined || Array.isArray(record[k]));
}

/**
 * Record a successful check against the feed server that found nothing newer:
 * the cache is current, so the staleness warning must not keep firing.
 */
export async function touchFeedCheck(metadataPath: string): Promise<void> {
  try {
    const meta = JSON.parse(await readFile(metadataPath, 'utf-8')) as Record<string, unknown>;
    if (!meta || typeof meta !== 'object' || Array.isArray(meta)) return;
    await writeFile(metadataPath, JSON.stringify({ ...meta, lastCheckAt: new Date().toISOString() }, null, 2));
  } catch {
    // No metadata yet (nothing cached): nothing to refresh
  }
}

// ── Deserialization helpers ─────────────────────────────────────────

export function deserializePatterns(serialized: SerializedRegExp[]): RegExp[] {
  return serialized.map((s) => new RegExp(s.source, s.flags ?? ''));
}

export function deserializeBinaryPatterns(serialized: SerializedBinaryPattern[]): BinaryPattern[] {
  return serialized.map((s) => {
    if (s.type === 'buffer') {
      return { name: s.name, pattern: Buffer.from(s.pattern, 'hex'), type: 'buffer' as const };
    }
    return { name: s.name, pattern: new RegExp(s.pattern, s.flags ?? ''), type: 'regex' as const };
  });
}

// ── Merge logic ─────────────────────────────────────────────────────

function dedupeStrings(base: string[], additions: string[]): string[] {
  const set = new Set(base);
  for (const item of additions) set.add(item);
  return [...set];
}

function dedupeRegExps(base: RegExp[], additions: RegExp[]): RegExp[] {
  const seen = new Set(base.map((r) => `${r.source}|||${r.flags}`));
  const result = [...base];
  for (const r of additions) {
    const key = `${r.source}|||${r.flags}`;
    if (!seen.has(key)) {
      seen.add(key);
      result.push(r);
    }
  }
  return result;
}

function dedupeBinaryPatterns(base: BinaryPattern[], additions: BinaryPattern[]): BinaryPattern[] {
  const seen = new Set(base.map((p) => `${p.name}|||${p.type}`));
  const result = [...base];
  for (const p of additions) {
    const key = `${p.name}|||${p.type}`;
    if (!seen.has(key)) {
      seen.add(key);
      result.push(p);
    }
  }
  return result;
}

export function mergeFeedIntoDatabase(bundled: IOCDatabase, feedData: IOCFeedData): IOCDatabase {
  return {
    c2Ips: dedupeStrings(bundled.c2Ips, feedData.c2Ips ?? []),
    maliciousDomains: dedupeStrings(bundled.maliciousDomains, feedData.maliciousDomains ?? []),
    fileHashes: dedupeStrings(bundled.fileHashes, feedData.fileHashes ?? []),
    maliciousPublishers: dedupeStrings(bundled.maliciousPublishers, feedData.maliciousPublishers ?? []),
    maliciousSkillPatterns: dedupeRegExps(
      bundled.maliciousSkillPatterns,
      feedData.maliciousSkillPatterns ? deserializePatterns(feedData.maliciousSkillPatterns) : [],
    ),
    trustedSkillNames: dedupeStrings(bundled.trustedSkillNames, feedData.trustedSkillNames ?? []),
    trustedMCPPackages: dedupeStrings(bundled.trustedMCPPackages, feedData.trustedMCPPackages ?? []),
    binaryPatterns: dedupeBinaryPatterns(
      bundled.binaryPatterns,
      feedData.binaryPatterns ? deserializeBinaryPatterns(feedData.binaryPatterns) : [],
    ),
  };
}

// ── Staleness check ─────────────────────────────────────────────────

export function isFeedStale(thresholdDays: number = DEFAULT_STALENESS_DAYS, metadataDir: string = IOC_DIR): boolean {
  let raw: string;
  try {
    raw = readFileSync(join(metadataDir, METADATA_FILE), 'utf-8');
  } catch {
    // No metadata file: user has never fetched a remote feed.
    // Treat as "not opted in" rather than stale — bundled data is the baseline.
    return false;
  }
  try {
    const meta: IOCFeedMetadata = JSON.parse(raw);
    const lastCheck = new Date(meta.lastCheckAt).getTime();
    if (isNaN(lastCheck)) return false;
    const ageMs = Date.now() - lastCheck;
    return ageMs > thresholdDays * 24 * 60 * 60 * 1000;
  } catch {
    return false;
  }
}

// ── Cached feed loader ──────────────────────────────────────────────

/** Remove a cached feed, its signature and its metadata. */
async function removeCachedFeed(feedDir: string): Promise<void> {
  await Promise.all([FEED_FILE, SIG_FILE, METADATA_FILE].map((f) => unlink(join(feedDir, f)).catch(() => {})));
}

export async function loadCachedFeed(
  feedDir: string = IOC_DIR,
  publicKeyPem: string = IOC_FEED_PUBLIC_KEY,
): Promise<IOCFeedData | null> {
  try {
    const feedPath = join(feedDir, FEED_FILE);
    const sigPath = join(feedDir, SIG_FILE);

    let feedBytes: Buffer;
    let sigContent: string;
    try {
      feedBytes = await readFile(feedPath);
      sigContent = (await readFile(sigPath, 'utf-8')).trim();
    } catch {
      return null; // files don't exist
    }

    // Re-verify signature on every load (catches local tampering)
    if (!verifyFeedSignature(feedBytes, sigContent, publicKeyPem)) {
      // Tampered — delete both files
      await unlink(feedPath).catch(() => {});
      await unlink(sigPath).catch(() => {});
      // Bundled data still applies, but the user should know the update is gone
      console.error(`Warning: the cached IOC feed failed signature verification and was removed; run \`vaso update\` to re-install it.`);
      return null;
    }

    const feed: IOCFeed = JSON.parse(feedBytes.toString('utf-8'));
    // An advisory feed cached here by an older `vaso update --url` is no IOC
    // data. Remove it with its metadata, whose version is the advisory feed's
    // and would otherwise refuse every real IOC feed as "not newer".
    if (!isIOCFeedData(feed.data)) {
      await removeCachedFeed(feedDir);
      return null;
    }
    return feed.data;
  } catch {
    return null;
  }
}

// ── Fetch and update ────────────────────────────────────────────────

export interface FetchOptions {
  feedUrl?: string;
  /** Fetch even when the cached feed isn't stale. */
  force?: boolean;
  /** Re-install a feed of the same version as the cache (repairs a damaged
   *  cache). An older feed is never installed — that would roll back
   *  indicators with a replayed, validly signed old feed. */
  reinstall?: boolean;
  feedDir?: string;
  publicKeyPem?: string;
}

export async function fetchAndUpdateFeed(options: FetchOptions = {}): Promise<UpdateResult> {
  const feedUrl = options.feedUrl ?? DEFAULT_FEED_URL;
  const feedDir = options.feedDir ?? IOC_DIR;
  const publicKeyPem = options.publicKeyPem ?? IOC_FEED_PUBLIC_KEY;
  const force = options.force ?? false;

  // Ensure directory exists
  await mkdir(feedDir, { recursive: true });

  // A cached feed that is missing or fails its signature (deleted on load)
  // is no cache at all: fetch, and re-install even the same version
  const cacheUsable = (await loadCachedFeed(feedDir, publicKeyPem)) !== null;

  // Unless forced, skip when a cached feed exists and isn't stale.
  // (Missing metadata means no cache yet — proceed with the fetch.)
  if (!force && cacheUsable && existsSync(join(feedDir, METADATA_FILE)) && !isFeedStale(DEFAULT_STALENESS_DAYS, feedDir)) {
    return { success: true, message: 'Feed is up to date (not stale).' };
  }

  // Load current metadata for version comparison
  let currentVersion = 0;
  try {
    const metaRaw = await readFile(join(feedDir, METADATA_FILE), 'utf-8');
    const meta: IOCFeedMetadata = JSON.parse(metaRaw);
    currentVersion = meta.feedVersion;
  } catch {
    // No existing metadata
  }

  // Fetch feed and signature
  // Feed, then signature — one at a time, each body read before the next
  // request: two parallel responses with one body left unread can trip
  // undici when the server closes the connection.
  const get = async (url: string, maxBytes: number): Promise<{ status: number; body?: Buffer }> => {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
    try {
      const res = await fetch(url, { signal: controller.signal });
      if (!res.ok) {
        await res.body?.cancel().catch(() => undefined);
        return { status: res.status };
      }
      return { status: res.status, body: await readBodyCapped(res, maxBytes) };
    } finally {
      clearTimeout(timeout);
    }
  };

  let feedBytes: Buffer;
  let sigBase64: string;
  try {
    const feedRes = await get(feedUrl, MAX_FEED_BYTES);
    if (!feedRes.body) return { success: false, message: `Feed fetch failed: HTTP ${feedRes.status}` };
    const sigRes = await get(feedUrl + '.sig', MAX_SIGNATURE_BYTES);
    if (!sigRes.body) return { success: false, message: `Signature fetch failed: HTTP ${sigRes.status}` };
    feedBytes = feedRes.body;
    sigBase64 = sigRes.body.toString('utf-8').trim();
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    return { success: false, message: `Failed to fetch feed: ${msg}` };
  }

  // Signature first: nothing in an unsigned response is trusted — not even
  // its version number, which would otherwise decide what is reported
  if (!verifyFeedSignature(feedBytes, sigBase64, publicKeyPem)) {
    return { success: false, message: 'Feed signature verification failed.' };
  }

  let feed: IOCFeed;
  try {
    feed = JSON.parse(feedBytes.toString('utf-8'));
    if (!feed.meta || typeof feed.meta.version !== 'number' || !feed.data) {
      return { success: false, message: 'Invalid feed format: missing meta or data fields.' };
    }
    if (!isIOCFeedData(feed.data)) {
      return { success: false, message: 'Not an IOC feed (is this the advisory feed? use --advisory-url).' };
    }
  } catch {
    return { success: false, message: 'Invalid feed JSON.' };
  }

  // Reject downgrades
  if (feed.meta.version < currentVersion || (feed.meta.version === currentVersion && !options.reinstall && cacheUsable)) {
    // The server is current only when it serves the cached version; an older
    // mirror must not silence the staleness warning
    if (cacheUsable && feed.meta.version === currentVersion) await touchFeedCheck(join(feedDir, METADATA_FILE));
    return {
      success: true,
      message: `Feed version ${feed.meta.version} is not newer than cached version ${currentVersion}.`,
    };
  }

  // Persist feed, signature, and metadata
  await writeFile(join(feedDir, FEED_FILE), feedBytes);
  await writeFile(join(feedDir, SIG_FILE), sigBase64);

  const metadata: IOCFeedMetadata = {
    lastUpdated: new Date().toISOString(),
    feedVersion: feed.meta.version,
    feedUrl,
    lastCheckAt: new Date().toISOString(),
  };
  await writeFile(join(feedDir, METADATA_FILE), JSON.stringify(metadata, null, 2));

  // Count new indicators
  const data = feed.data;
  const newIndicators = {
    c2Ips: data.c2Ips?.length ?? 0,
    maliciousDomains: data.maliciousDomains?.length ?? 0,
    fileHashes: data.fileHashes?.length ?? 0,
    maliciousPublishers: data.maliciousPublishers?.length ?? 0,
    maliciousSkillPatterns: data.maliciousSkillPatterns?.length ?? 0,
    trustedSkillNames: data.trustedSkillNames?.length ?? 0,
    trustedMCPPackages: data.trustedMCPPackages?.length ?? 0,
    binaryPatterns: data.binaryPatterns?.length ?? 0,
  };

  return {
    success: true,
    message: `Feed updated to version ${feed.meta.version}.`,
    newIndicators,
    feedVersion: feed.meta.version,
  };
}
